(752, 2, '2021-03-13 03:38:38', '2021-03-13 03:38:38', 'a:10:{s:4:\"type\";s:4:\"text\";s:12:\"instructions\";s:228:\"In the same order as the purchase links and separated by a comma and a space, give the plain name where they lead. For example, if purchase_link reads: https://amazon.com, https://google.com THEN this should read: Amazon, Google\";s:8:\"required\";i:1;s:17:\"conditional_logic\";i:0;s:7:\"wrapper\";a:3:{s:5:\"width\";s:0:\"\";s:5:\"class\";s:0:\"\";s:2:\"id\";s:0:\"\";}s:13:\"default_value\";s:0:\"\";s:11:\"placeholder\";s:0:\"\";s:7:\"prepend\";s:0:\"\";s:6:\"append\";s:0:\"\";s:9:\"maxlength\";s:0:\"\";}', 'purchase_links_names', 'purchase_links_names', 'publish', 'closed', 'closed', '', 'field_604c31d7b1ec4', '', '', '2021-03-13 08:35:03', '2021-03-13 08:35:03', '', 749, 'https://benyakiredits.com/?post_type=acf-field&#038;p=752', 2, 'acf-field', '', 0),
(753, 2, '2021-03-13 03:38:38', '2021-03-13 03:38:38', 'a:12:{s:4:\"type\";s:12:\"relationship\";s:12:\"instructions\";s:87:\"Stories which have some relationship to  this book (i.e. prologue, extra chapter, etc.)\";s:8:\"required\";i:0;s:17:\"conditional_logic\";i:0;s:7:\"wrapper\";a:3:{s:5:\"width\";s:0:\"\";s:5:\"class\";s:0:\"\";s:2:\"id\";s:0:\"\";}s:9:\"post_type\";a:1:{i:0;s:10:\"shortstory\";}s:8:\"taxonomy\";s:0:\"\";s:7:\"filters\";a:3:{i:0;s:6:\"search\";i:1;s:9:\"post_type\";i:2;s:8:\"taxonomy\";}s:8:\"elements\";s:0:\"\";s:3:\"min\";s:0:\"\";s:3:\"max\";s:0:\"\";s:13:\"return_format\";s:6:\"object\";}', 'related_stories', 'related_stories', 'publish', 'closed', 'closed', '', 'field_604c3207b1ec5', '', '', '2021-03-13 03:38:38', '2021-03-13 03:38:38', '', 749, 'https://benyakiredits.com/?post_type=acf-field&p=753', 3, 'acf-field', '', 0),
