(758, 2, '2021-03-13 03:38:40', '2021-03-13 03:38:40', 'a:10:{s:4:\"type\";s:4:\"text\";s:12:\"instructions\";s:36:\"Information about the cover designer\";s:8:\"required\";i:0;s:17:\"conditional_logic\";a:1:{i:0;a:1:{i:0;a:2:{s:5:\"field\";s:19:\"field_604c3317b1ec9\";s:8:\"operator\";s:7:\"!=empty\";}}}s:7:\"wrapper\";a:3:{s:5:\"width\";s:0:\"\";s:5:\"class\";s:0:\"\";s:2:\"id\";s:0:\"\";}s:13:\"default_value\";s:0:\"\";s:11:\"placeholder\";s:0:\"\";s:7:\"prepend\";s:0:\"\";s:6:\"append\";s:0:\"\";s:9:\"maxlength\";s:0:\"\";}', 'cover_designer_bio', 'cover_designer_bio', 'publish', 'closed', 'closed', '', 'field_604c3340b1eca', '', '', '2021-03-13 03:38:40', '2021-03-13 03:38:40', '', 749, 'https://benyakiredits.com/?post_type=acf-field&p=758', 8, 'acf-field', '', 0);
